						bk_pm_module_vote_boot_cp1_ctrl(PM_BOOT_CP1_MODULE_NAME_APP,PM_POWER_MODULE_STATE_ON);
					}
				}
				break;
                default:
                    break;
            }
        }
    }

	return  ret;
