static int ipc_heartbeat_worker(int argc, char **argv)
{
  static uint32_t heartbeat_sequence = 1;
  static uint32_t heartbeat_busy;
  static uint32_t heartbeat_nolink;
  static uint32_t heartbeat_timeout;
  static uint32_t heartbeat_other;
  int ret;

  (void)argc;
  (void)argv;
  ret = bind_worker_to_primary();
  g_heartbeat_result = ret < 0 ? -EXDEV : OK;
  nxsem_post(&g_heartbeat_sem);
  if (ret < 0)
    {
      return -EXDEV;
    }

  for (;;)
    {
      nxsig_usleep(2000000);
      ret = bk7258_mailbox_send_pwc(PM_OPENVELA_HEARTBEAT_CMD,
                                    heartbeat_sequence++,
                                    PM_OPENVELA_READY_PROTO_V1, 0);
      if (ret >= 0)
        {
          ret = bk7258_mailbox_wait_pwc(PM_TRANSPORT_TIMEOUT_MS);
        }

      if (ret < 0)
        {
          uint32_t failures;

          if (ret == -EBUSY)
            {
              failures = ++heartbeat_busy;
            }
          else if (ret == -ENOLINK)
            {
              failures = ++heartbeat_nolink;
            }
          else if (ret == -ETIMEDOUT)
            {
              failures = ++heartbeat_timeout;
            }
          else
            {
              failures = ++heartbeat_other;
            }

          if ((failures & (failures - 1u)) == 0)
            {
              syslog(LOG_ERR,
                      "heartbeat send=%d busy=%lu link=%lu timeout=%lu "
                      "other=%lu\n",
                      ret, (unsigned long)heartbeat_busy,
                      (unsigned long)heartbeat_nolink,
                      (unsigned long)heartbeat_timeout,
                      (unsigned long)heartbeat_other);
            }
        }
    }
  return 0;
}

